<template>
  <div>
    <div class="page-header"><div><h2>业务人员管理</h2><p>统一新增和查看订单员、分拣员及配送员</p></div><div class="actions"><el-button type="danger" plain :disabled="!selected.length" @click="batchRemove">批量删除（{{ selected.length }}）</el-button><el-button type="primary" @click="openCreate"><el-icon><Plus /></el-icon>新增人员</el-button></div></div>
    <el-card class="panel">
      <div class="toolbar"><el-radio-group v-model="filter"><el-radio-button value="all">全部</el-radio-button><el-radio-button value="order_clerk">订单员</el-radio-button><el-radio-button value="sorter">分拣员</el-radio-button><el-radio-button value="delivery">配送员</el-radio-button></el-radio-group><el-input v-model="keyword" clearable placeholder="搜索姓名或电话" style="width:260px" /></div>
      <el-table :data="filtered" @selection-change="selected = $event"><el-table-column type="selection" width="46" :selectable="isSelectable"/><el-table-column prop="name" label="姓名" min-width="150"/><el-table-column label="人员类型" width="110"><template #default="s"><el-tag :type="staffTypeTag(s.row.staff_type)">{{staffTypeLabel(s.row.staff_type)}}</el-tag></template></el-table-column><el-table-column prop="phone" label="联系电话" min-width="150"><template #default="s">{{s.row.phone||'—'}}</template></el-table-column><el-table-column prop="remark" label="备注" min-width="180"><template #default="s">{{s.row.remark||'—'}}</template></el-table-column><el-table-column label="状态" width="90"><template #default="s"><el-tag :type="s.row.active?'success':'info'">{{s.row.active?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="285"><template #default="s"><el-tag v-if="s.row.staff_type==='order_clerk'" type="info" effect="plain">请在账号管理中维护</el-tag><template v-else><el-button link type="success" :disabled="!s.row.active" @click="openMobile(s.row)">手机入口</el-button><el-button link type="primary" @click="openEdit(s.row)">编辑</el-button><el-button link :type="s.row.active?'warning':'success'" @click="toggle(s.row)">{{s.row.active?'禁用':'启用'}}</el-button><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></template></el-table-column></el-table>
    </el-card>
    <el-dialog v-model="visible" :title="form.id?'编辑人员':'新增人员'" width="560px"><el-form label-width="90px"><el-form-item label="姓名" required><el-input v-model="form.name"/></el-form-item><el-form-item label="人员类型" required><el-radio-group v-model="form.staff_type"><el-radio v-if="!form.id" value="order_clerk">订单员</el-radio><el-radio value="sorter">分拣员</el-radio><el-radio value="delivery">配送员</el-radio></el-radio-group></el-form-item><template v-if="form.staff_type==='order_clerk'"><el-alert title="订单员需要登录系统处理微信订单，因此会同时创建登录账号。" type="info" :closable="false"/><el-form-item label="登录账号" required class="account-field"><el-input v-model="form.username" placeholder="建议使用姓名拼音或工号"/></el-form-item><el-form-item label="登录密码" required><el-input v-model="form.password" type="password" show-password placeholder="至少6位"/></el-form-item></template><template v-else><el-form-item v-if="!form.id" label="工作密码" required><el-input v-model="form.work_pin" maxlength="6" inputmode="numeric" show-password placeholder="设置6位数字，供本人手机验证"/></el-form-item><el-form-item label="联系电话"><el-input v-model="form.phone"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea"/></el-form-item><el-form-item v-if="form.id" label="状态"><el-switch v-model="form.active"/></el-form-item></template></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog>
    <el-dialog v-model="mobileVisible" :title="`${mobileData.name}的手机任务入口`" width="520px" class="mobile-dialog"><div class="mobile-access"><img :src="mobileData.qr" alt="手机入口二维码"/><h3>微信扫码后收藏页面</h3><p>{{mobileData.type==='sorter'?'本人只会看到分配给自己的分拣任务':'本人只会看到分配给自己的配送及装车任务'}}</p><el-input :model-value="mobileData.url" readonly><template #append><el-button @click="copyMobileLink">复制链接</el-button></template></el-input><el-alert :title="mobileData.hasPin?'已启用6位工作密码，别人拿到二维码也不能直接操作。':'尚未设置工作密码，人员暂时无法登录，请先设置。'" :type="mobileData.hasPin?'success':'error'" :closable="false" show-icon/><el-alert title="手机丢失时请重新生成入口，旧链接和已登录手机都会立即失效。" type="warning" :closable="false" show-icon/></div><template #footer><el-button @click="setWorkPin">{{mobileData.hasPin?'修改工作密码':'设置工作密码'}}</el-button><el-button @click="resetMobileLink">重新生成入口</el-button><el-button type="primary" @click="mobileVisible=false">完成</el-button></template></el-dialog>
  </div>
</template>
<script setup>
import { computed,onMounted,reactive,ref } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import QRCode from 'qrcode'
import { createAccount,createStaff,deleteStaff,getCustomerOrderClerks,getStaff,resetStaffMobileToken,setStaffWorkPin,updateStaff } from '@/api'
const rows=ref([]),clerks=ref([]),selected=ref([]),visible=ref(false),mobileVisible=ref(false),filter=ref('all'),keyword=ref('')
const mobileData=reactive({id:null,name:'',type:'',url:'',qr:'',hasPin:false})
const blank=()=>({id:null,name:'',staff_type:'sorter',phone:'',remark:'',active:true,username:'',password:'',work_pin:''})
const form=reactive(blank())
const allRows=computed(()=>[...clerks.value.map(row=>({...row,id:`order-clerk-${row.id}`,account_id:row.id,staff_type:'order_clerk',active:true,phone:null,remark:'订单员账号'})),...rows.value])
const filtered=computed(()=>allRows.value.filter(r=>(filter.value==='all'||r.staff_type===filter.value)&&(!keyword.value||`${r.name}${r.phone||''}`.toLowerCase().includes(keyword.value.toLowerCase()))))
const staffTypeLabel=type=>({order_clerk:'订单员',sorter:'分拣员',delivery:'配送员'}[type]||type)
const staffTypeTag=type=>type==='order_clerk'?'warning':type==='sorter'?'primary':'success'
const isSelectable=row=>row.staff_type!=='order_clerk'
const load=async()=>[rows.value,clerks.value]=await Promise.all([getStaff(),getCustomerOrderClerks()])
const openCreate=()=>{Object.assign(form,blank());visible.value=true}
const openEdit=r=>{Object.assign(form,blank(),r);visible.value=true}
const setMobileData=async row=>{const url=`${window.location.origin}/mobile-tasks?token=${row.mobile_token}`;Object.assign(mobileData,{id:row.id,name:row.name,type:row.staff_type,url,qr:await QRCode.toDataURL(url,{width:260,margin:1,errorCorrectionLevel:'M'}),hasPin:row.has_work_pin})}
const openMobile=async row=>{if(!row.mobile_token)return ElMessage.warning('该人员尚未生成手机入口，请刷新页面后重试');await setMobileData(row);mobileVisible.value=true}
const copyMobileLink=async()=>{try{await navigator.clipboard.writeText(mobileData.url)}catch{const input=document.createElement('textarea');input.value=mobileData.url;document.body.appendChild(input);input.select();document.execCommand('copy');input.remove()}ElMessage.success('手机入口链接已复制')}
const resetMobileLink=async()=>{await ElMessageBox.confirm('重新生成后，原二维码和链接会立即失效，确认继续吗？','重新生成手机入口',{type:'warning'});const result=await resetStaffMobileToken(mobileData.id);const row=rows.value.find(item=>item.id===mobileData.id);if(row)row.mobile_token=result.mobile_token;await setMobileData(row);ElMessage.success(result.message)}
const setWorkPin=async()=>{const {value}=await ElMessageBox.prompt('请输入6位数字工作密码。修改后，之前登录的手机需要重新验证。','设置工作密码',{inputType:'password',inputPattern:/^\d{6}$/,inputErrorMessage:'请输入6位数字'});await setStaffWorkPin(mobileData.id,value);const row=rows.value.find(item=>item.id===mobileData.id);if(row)row.has_work_pin=true;mobileData.hasPin=true;ElMessage.success('工作密码已设置，请单独告知本人')}
const payload=r=>({name:r.name.trim(),staff_type:r.staff_type,phone:r.phone||null,remark:r.remark||null,active:r.active})
const save=async()=>{if(!form.name.trim())return ElMessage.warning('请输入姓名');if(form.staff_type==='order_clerk'){if(!form.username.trim())return ElMessage.warning('请输入订单员登录账号');if(form.password.length<6)return ElMessage.warning('登录密码至少6位');await createAccount({username:form.username.trim(),password:form.password,name:form.name.trim(),role:'order_clerk',supplier_id:null,active:true,permissions:['dashboard','sales_order_management','sales_summary','wecom_management','complaint_management','label_printing','picking_management','picking_monitor']})}else if(form.id)await updateStaff(form.id,payload(form));else{if(!/^\d{6}$/.test(form.work_pin))return ElMessage.warning('请设置6位数字工作密码');const created=await createStaff(payload(form));await setStaffWorkPin(created.id,form.work_pin)}ElMessage.success(form.staff_type==='order_clerk'?'订单员账号已创建':'保存成功');visible.value=false;load()}
const toggle=async r=>{await updateStaff(r.id,{...payload(r),active:!r.active});ElMessage.success('状态已更新');load()}
const remove=async r=>{await ElMessageBox.confirm(`确认提交人员“${r.name}”的删除申请吗？管理员审核前不会删除。`,'提交删除申请',{type:'warning'});const res=await deleteStaff(r.id);ElMessage.success(res.message);load()}
const batchRemove=async()=>{await ElMessageBox.confirm(`确认提交 ${selected.value.length} 名人员的删除申请吗？`,'批量提交删除申请',{type:'warning'});for(const row of selected.value)await deleteStaff(row.id);ElMessage.success('批量删除申请已提交');load()}
onMounted(load)
</script>
<style scoped>.actions{display:flex;gap:10px}.account-field{margin-top:18px}.mobile-access{text-align:center}.mobile-access img{width:230px;height:230px}.mobile-access h3{margin:5px 0}.mobile-access p{color:#7d8999;margin:6px 0 16px}.mobile-access .el-alert{margin-top:15px;text-align:left}</style>
